<script setup lang="ts">
import { ref,onMounted,onUnmounted } from 'vue';
import axios from 'axios';
const profileDialog=ref<HTMLDialogElement|null>(null),avatarFile=ref<File|null>(null),profileBusy=ref(false);
const profile=ref({username:'',signature:'',location:'',qq:'',dormitory:''}),profileMessage=ref('');
async function saveProfile(){profileBusy.value=true;try{profile.value=(await axios.put('/api/profile',profile.value,{headers:await headers()})).data;if(avatarFile.value){const data=new FormData();data.append('file',avatarFile.value);await axios.post('/api/profile/avatar',data,{headers:await headers()});avatarFile.value=null;}profileMessage.value='资料已保存';window.dispatchEvent(new Event('profile-updated'));profileDialog.value?.close();}catch(e){window.dispatchEvent(new Event('profile-updated'));profileMessage.value=axios.isAxiosError(e)&&e.response?.status===409?'用户名已存在，请换一个':'保存未完成，请检查输入或头像后重试';}finally{profileBusy.value=false;}}

const items=ref<{id:number;title:string;status:string;price:number;description:string;location:string;imageUrl:string;kind:string}[]>([]),error=ref(''),busy=ref(false);
const publishDialog=ref<HTMLDialogElement|null>(null);
function openPublish(){kind.value='SELL';editing.value=null;title.value='';description.value='';price.value='';location.value='';resetPhoto();error.value='';publishDialog.value?.showModal();}
function closePublish(){if(!busy.value)publishDialog.value?.close();}
const editing=ref<number|null>(null), selectedPhoto=ref<File|null>(null),preview=ref(''),fileInputKey=ref(0);
let previewObjectUrl='';
function resetPhoto(url=''){if(previewObjectUrl)URL.revokeObjectURL(previewObjectUrl);previewObjectUrl='';selectedPhoto.value=null;preview.value=url;fileInputKey.value++;}
function selectPhoto(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(previewObjectUrl)URL.revokeObjectURL(previewObjectUrl);previewObjectUrl='';selectedPhoto.value=file||null;if(file){previewObjectUrl=URL.createObjectURL(file);preview.value=previewObjectUrl;}else preview.value=items.value.find(p=>p.id===editing.value)?.imageUrl||'';}
onUnmounted(()=>{if(previewObjectUrl)URL.revokeObjectURL(previewObjectUrl);});
const kind=ref('SELL');
const title=ref(''),description=ref(''),price=ref(''),location=ref('');
async function load(){try{items.value=(await axios.get('/api/my/products')).data;}catch{error.value='请先点击右上角登录，再刷新此页。';}}
async function headers(){return {'X-XSRF-TOKEN':(await axios.get('/api/auth/csrf')).data.token};}
async function edit(id:number){const p=items.value.find(x=>x.id===id);if(!p)return;editing.value=id;kind.value=p.kind||'SELL';resetPhoto(p.imageUrl);title.value=p.title;description.value=p.description;price.value=String(p.price);location.value=p.location;error.value='';publishDialog.value?.showModal();}
async function publish(){busy.value=true;error.value='';try{if(!editing.value){if(!selectedPhoto.value&&kind.value==='SELL'){error.value='请选择商品图片';return;}const data=new FormData();data.append('product',new Blob([JSON.stringify({title:title.value,description:description.value,price:price.value,location:location.value,kind:kind.value})],{type:'application/json'}));if(selectedPhoto.value){data.append('file',selectedPhoto.value);await axios.post('/api/my/products/publish',data,{headers:await headers()});}else{await axios.post('/api/my/products',{title:title.value,description:description.value,price:price.value,location:location.value,kind:kind.value},{headers:await headers()});}selectedPhoto.value=null;}else if(selectedPhoto.value){const data=new FormData();data.append('product',new Blob([JSON.stringify({title:title.value,description:description.value,price:price.value,location:location.value,kind:kind.value})],{type:'application/json'}));data.append('file',selectedPhoto.value);await axios.post('/api/my/products/'+editing.value+'/edit-with-image',data,{headers:await headers()});}else await axios.request({method:editing.value?'PUT':'POST',url:'/api/my/products'+(editing.value?'/'+editing.value:''),data:{title:title.value,description:description.value,price:price.value,location:location.value,kind:kind.value},headers:await headers()});editing.value=null;resetPhoto();title.value='';description.value='';price.value='';location.value='';publishDialog.value?.close();await load();}catch{error.value='发布失败，请检查输入及登录状态。';}finally{busy.value=false;}}
async function withdraw(id:number){if(!confirm('确认下架这件商品？'))return;try{await axios.post('/api/my/products/'+id+'/withdraw',null,{headers:await headers()});await load();}catch{error.value='下架失败，请刷新后重试。';}}
onMounted(async()=>{await load();try{profile.value=(await axios.get('/api/profile')).data;}catch{profileMessage.value='资料加载失败';}});
</script>
<template><section class="my-products"><div class="profile-heading"><div><p class="profile-eyebrow">SHANDONG UNIVERSITY / MY CAMPUS</p><h1>个人主页</h1><p>让闲置好物，在山大遇见新主人。</p></div><div class="profile-actions"><button class="profile-entry" type="button" @click="profileMessage='';profileDialog?.showModal()"><span class="sdu-stamp">山大</span><span class="no-face" aria-hidden="true"><span class="mask"><i></i><i></i><b>―</b></span></span><span>编辑个人资料<small>记录属于你的校园日常</small></span><span>↗</span></button><button type="button" class="publish-entry" @click="openPublish"><span class="sdu-stamp">山大</span><span class="fish-symbol" aria-hidden="true">><span>●</span>))°</span><span class="entry-copy"><strong>发布闲置</strong><small>校园好物 · 闲不住的生活</small></span><span class="entry-plus">＋</span></button></div></div><p role="alert">{{ error }}</p><dialog ref="publishDialog" class="publish-dialog" aria-labelledby="publish-title" @cancel="busy && $event.preventDefault()" @click="($event.target===publishDialog) && closePublish()"><button class="dialog-close" type="button" aria-label="关闭发布窗口" :disabled="busy" @click="closePublish">×</button><p class="dialog-eyebrow">山大好物 / CAMPUS REUSE</p><form @submit.prevent="publish"><h2 id="publish-title">{{ editing?'编辑商品':'发布校园好物' }}</h2><label>发布类型<select v-model="kind" :disabled="!!editing"><option value="SELL">出售闲置</option><option value="WANTED">感兴趣 / 求购</option></select></label><label>商品名称<input v-model="title" required maxlength="120"></label><label>商品描述<textarea v-model="description" required maxlength="5000"></textarea></label><label>{{kind==='WANTED'?'预算（元）':'价格（元）'}}<input v-model="price" required type="number" min="0.01" max="99999999.99" step="0.01"></label><label>交易地点<input v-model="location" required maxlength="120"></label><label>{{editing?'更换商品图片（可选）':'商品图片'}}<input :key="fileInputKey" type="file" accept="image/jpeg,image/png" :required="!editing&&kind==='SELL'" @change="selectPhoto"></label><img v-if="preview" class="edit-image-preview" :src="preview" alt="商品图片预览"><p role="alert" class="form-error">{{ error }}</p><small>求购可不附图片；编辑时不选新图则保留原图。</small><button :disabled="busy">{{ busy?'保存中…':editing?'保存修改':'发布商品' }}</button><button v-if="editing" type="button" @click="closePublish">取消编辑</button></form></dialog>
<dialog ref="profileDialog" class="publish-dialog" aria-labelledby="profile-title" @cancel="profileBusy && $event.preventDefault()"><button type="button" class="dialog-close" :disabled="profileBusy" aria-label="关闭资料窗口" @click="profileDialog?.close()">×</button><p class="dialog-eyebrow">山大 · 我的校园身份</p><h2 id="profile-title">编辑个人资料</h2><form @submit.prevent="saveProfile"><label>头像<input type="file" accept="image/jpeg,image/png" @change="avatarFile=($event.target as HTMLInputElement).files?.[0] || null"></label><label>用户名（也是登录账号）<input v-model="profile.username" required pattern="[a-zA-Z0-9_-]{3,32}" maxlength="32"></label><label>QQ联系方式<input v-model="profile.qq" inputmode="numeric" pattern="[0-9]{0,20}" maxlength="20"></label><label>个性签名<textarea v-model="profile.signature" maxlength="300"></textarea></label><label>宿舍楼<input v-model="profile.dormitory" maxlength="120" placeholder="例如：阅海居B2"></label><label>校园地点<input v-model="profile.location" maxlength="120"></label><p role="status">{{ profileMessage }}</p><button :disabled="profileBusy">{{profileBusy?'保存中…':'保存修改'}}</button></form></dialog><h2>我的出售与求购</h2><p v-if="!items.length">暂无发布记录。</p><article v-for="item in items" :key="item.id"><img class="thumbnail" :src="item.imageUrl" :alt="item.title"><RouterLink :to="'/market/'+item.id">{{item.kind==='WANTED'?'[求购] ':'[出售] '}}{{ item.title }}</RouterLink><span>¥ {{ item.price }} · {{ item.status==='AVAILABLE'?'在售':item.status==='RESERVED'?'已预订':item.status==='SOLD'?'已售出':'已下架' }}</span><button v-if="item.status==='AVAILABLE'" @click="edit(item.id)">编辑</button><button v-if="item.status==='AVAILABLE'" @click="withdraw(item.id)">下架</button></article></section></template>
<style scoped>.my-products{background:#f6f4ee;color:#293d3b;padding:40px max(6%,20px);flex:1}.my-products h1{font-size:32px;margin:0 0 15px}form{max-width:620px;background:white;padding:28px;border-radius:8px;margin:25px 0}label{display:block;font-size:14px;margin:18px 0}input,textarea{display:block;width:100%;padding:12px;margin-top:8px;border:1px solid #ccd3c9;font:inherit;border-radius:4px}textarea{min-height:100px}small{display:block;color:#8b7959;margin-bottom:18px}button{padding:12px 22px;border:0;border-radius:4px;background:#304b49;color:white}button:disabled{opacity:.5}article{display:flex;gap:25px;align-items:center;background:white;padding:20px;margin:12px 0;flex-wrap:wrap}a{color:#304b49}article span{font-size:13px}.thumbnail{width:70px;height:70px;object-fit:contain}.edit-image-preview{width:100%;max-height:200px;object-fit:contain;border-radius:8px;background:#f0eee6;margin:10px 0}.profile-heading{display:flex;justify-content:space-between;align-items:center;gap:25px;margin:5px 0 45px}.profile-eyebrow{font-size:10px;letter-spacing:2px;color:#92724b}.publish-entry{display:flex;align-items:center;gap:16px;background:#ffe56b;color:#342c23;border:1px solid #f3d550;border-radius:18px;padding:21px 25px;box-shadow:0 8px 0 #ddc15b30;transition:transform .2s}.publish-entry:hover{transform:translateY(-3px)}.sdu-stamp{display:grid;place-items:center;width:44px;height:44px;border:2px solid #983f40;color:#983f40;font-family:serif;font-size:18px;border-radius:50%;transform:rotate(-9deg)}.fish-symbol{font-size:24px;font-weight:bold;letter-spacing:-4px}.fish-symbol span{font-size:15px}.entry-copy{text-align:left}.entry-copy strong{font-size:20px;letter-spacing:2px}.entry-copy small{color:#665b38;font-size:10px;margin:6px 0 0}.entry-plus{font-size:28px;margin-left:15px}.publish-dialog{position:fixed;width:min(610px,calc(100% - 32px));max-height:88svh;padding:30px;border:1px solid #ffffff80;border-radius:18px;background:#fffaf2;color:#293d3b;box-shadow:0 30px 90px #0004;overflow:auto}.publish-dialog::backdrop{background:#142a35a6;backdrop-filter:blur(7px)}.publish-dialog form{padding:0;background:none;margin:12px 0 0;max-width:none}.publish-dialog h2{font-size:25px;margin:12px 0 25px}.dialog-eyebrow{font-size:10px;color:#967449;letter-spacing:2px;margin:0}.dialog-close{position:absolute;right:16px;top:12px;background:transparent;color:#52665d;font-size:26px;padding:4px 10px}.form-error{color:#a34536;font-size:13px}.publish-dialog form>button{margin-right:12px}@media(max-width:700px){.profile-heading{align-items:stretch;flex-direction:column}.publish-entry{justify-content:center}.publish-dialog{padding:24px}.publish-entry .entry-plus{margin-left:auto}}@media(prefers-reduced-motion:reduce){.publish-entry{transition:none}}
.profile-editor{padding:20px;background:#fffaf2;border:1px solid #e8e2d4;border-radius:10px;margin-bottom:30px}.profile-editor summary{cursor:pointer;font-size:15px}.profile-entry{display:flex;align-items:center;gap:18px;background:#eee7dc;color:#3d3935;border:1px solid #d9cec0;border-radius:18px;padding:18px 24px;margin:0 0 30px;text-align:left}.profile-entry small{font-size:10px;margin:6px 0 0}.no-face{position:relative;display:block;width:42px;height:59px;background:#24232c;border-radius:45% 45% 20% 20%}.mask{position:absolute;top:5px;left:9px;width:25px;height:36px;border-radius:45%;background:#fff9e8;display:flex;justify-content:space-around;padding:10px 3px}.mask i{width:4px;height:3px;background:#36333d;box-shadow:0 6px #9f8daf,0 -5px #9f8daf}.mask b{position:absolute;bottom:3px;font-size:11px;font-weight:400}.profile-entry:hover{background:#e8decd}
.profile-actions{display:flex;gap:16px;align-items:stretch}.profile-actions .profile-entry,.profile-actions .publish-entry{margin:0;flex:1;min-height:98px;padding:16px}.profile-actions .profile-entry>span:nth-child(3){white-space:nowrap}.profile-actions .entry-copy strong{font-size:17px}.profile-actions .entry-plus{margin-left:0}@media(max-width:1100px){.profile-heading{flex-direction:column;align-items:stretch}.profile-actions{width:100%}}@media(max-width:550px){.profile-actions{gap:8px}.profile-actions .sdu-stamp{display:none}.profile-actions .profile-entry,.profile-actions .publish-entry{padding:12px;gap:8px}.profile-actions small{font-size:9px}.profile-actions .entry-copy strong{font-size:15px}}
select{display:block;width:100%;padding:12px;border:1px solid #ccd3c9;border-radius:4px;margin-top:8px;background:white;font:inherit}</style>
